import React, { useRef, useState } from "react";
import { Avatar, Button, Dialog, DialogActions, DialogContent, IconButton, Slide, Stack, Typography, } from "@mui/material";
import { faker } from "@faker-js/faker";
import { ZegoExpressEngine } from "zego-express-engine-webrtc";
import { useDispatch, useSelector } from "react-redux";
import { useEffect } from "react";
import axiosInstance from "../../../utils/axios";
import { ResetAudioCallQueue, UpdateAudioCallDialog, UpdateCallStatus } from "../../../redux/slices/audioCall";
import webSocketService from "../../../webSocketService";
import { PhoneX } from "phosphor-react";

const Transition = React.forwardRef(function Transition(props, ref) {
  return <Slide direction="up" ref={ref} {...props} />;
});

const CallDialog = ({ open, handleClose }) => {

  const user_id = window.localStorage.getItem("user_id");
  const dispatch = useDispatch();
  const { user } = useSelector((state) => state.app);
  const audioStreamRef = useRef(null);
  const subscriptions = useRef([]);
  //* Use params from call_details if available => like in case of receiver's end
  const [call_details] = useSelector((state) => state.audioCall.call_queue);
  const { incoming, status } = useSelector((state) => state.audioCall);
  const { token } = useSelector((state) => state.auth);
  const appID = 159164384;
  const server = "wss://webliveroom159164384-api-bak.coolzcloud.com/ws";

  const [userBusy, setUserBusy] = useState(false);

  // roomID => ID of conversation => current_conversation.id
  // token => generate on backend & get on App
  // streamID => Other user's ID
  // userID => ID of this user
  // userName => slug formed by user's name

  const roomID = call_details?.roomID;
  const streamID = call_details?.streamID;
  const userID = call_details?.userID;
  const userName = call_details?.userName;

  // Step 1
  // Initialize the ZegoExpressEngine instance
  const zg = new ZegoExpressEngine(appID, server);
  zg.setLogConfig({ logLevel: "disable" })


  const handleDisconnect = (event, reason) => {
    if (reason && reason === "backdropClick") {
      return;
    } else {
      webSocketService.sendMessage("/app/end_audio_call", JSON.stringify({ ...call_details }));

      if (audioStreamRef.current) {
        audioStreamRef.current.getTracks().forEach((track) => {
          track.stop();
        });
      };

      zg.stopPublishingStream(streamID);
      zg.stopPlayingStream(userID);
      zg.destroyStream(audioStreamRef.current);
      zg.logoutRoom(roomID);

      dispatch(ResetAudioCallQueue());
      dispatch(UpdateCallStatus({ status: "" }));
      handleClose();
    }
  };

  useEffect(() => {

    if (!incoming) {
      webSocketService.sendMessage("/app/start_audio_call", JSON.stringify({
        to: streamID,
        from: userID,
        roomID,
      }));
    }

    // const timer = setTimeout(() => {
    //   webSocketService.sendMessage("/app/audio_call_not_picked", JSON.stringify({ to: call_details?.streamID, from: userID }));
    // }, 30 * 1000);

    const end_audio_call = webSocketService.subscribe(`/user/${user_id}/topic/end_audio_call`, (data) => {
      dispatch(UpdateCallStatus({ status: "" }));
      handleDisconnect();
    });
    subscriptions.current.push(end_audio_call);

    const audio_call_missed = webSocketService.subscribe(`/user/${user_id}/topic/audio_call_missed`, (data) => {
      handleDisconnect();
    });
    subscriptions.current.push(audio_call_missed);

    const audio_call_accepted = webSocketService.subscribe(`/user/${user_id}/topic/audio_call_accepted`, (data) => {
      dispatch(UpdateCallStatus({ status: "ONGOING" }));
      // clearTimeout(timer);
    });
    subscriptions.current.push(audio_call_accepted);

    const audio_call_denied = webSocketService.subscribe(`/user/${user_id}/topic/audio_call_denied`, (data) => {
      handleDisconnect();
    });
    subscriptions.current.push(audio_call_denied);

    const on_another_audio_call = webSocketService.subscribe(`/user/${user_id}/topic/on_another_audio_call`, (data) => {
      setUserBusy(true);
    });
    subscriptions.current.push(on_another_audio_call);

    let this_token;
    async function fetchToken() {
      const response = await axiosInstance.post("/user/generate-zego-token", {
        userId: userID,
        room_id: roomID,
      }, {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
      });
      // console.log(response, "TOKEN RESPONSE");
      this_token = response.data.token.data;
    }
    fetchToken();
    // Step 2 => Check browser compatibility

    zg.checkSystemRequirements()
      .then((result) => {
        // The [result] indicates whether it is compatible. It indicates WebRTC is supported when the [webRTC] is [true]. For more results, see the API documents.

        // {
        //   webRTC: true,
        //   customCapture: true,
        //   camera: true,
        //   microphone: true,
        //   videoCodec: { H264: true, H265: false, VP8: true, VP9: true },
        //   screenSharing: true,
        //   errInfo: {}
        // }
        // console.log(result);

        const { webRTC, microphone } = result;

        if (webRTC && microphone) {
          zg.loginRoom(roomID, this_token, { userID, userName }, { userUpdate: true })
            .then(async (result) => {
              // console.log(result);

              // After calling the CreateStream method, you need to wait for the ZEGOCLOUD server to return the local stream object before any further operation.
              const localStream = await zg.createStream({
                camera: { audio: true, video: false },
              });

              audioStreamRef.current = localStream;
              // Get the audio tag.
              const localAudio = document.getElementById("local-audio");
              // The local stream is a MediaStream object. You can render audio by assigning the local stream to the srcObject property of video or audio.

              if (localStream) {
                localAudio.srcObject = localStream;
              }

              // localStream is the MediaStream object created by calling creatStream in the previous step.
              zg.startPublishingStream(streamID, localStream);

              zg.on("publisherStateUpdate", (result) => {
                // Callback for updates on stream publishing status.
                // ...
                // console.log(result);
                // * we can use this info to show connection status
              });

              zg.on("publishQualityUpdate", (streamID, stats) => {
                // Callback for reporting stream publishing quality.
                // ...
                // console.log(streamID, stats);
                // * we can use this info to show local audio stream quality
              });
            })
            .catch((error) => {
              // console.log(error);
            });

          // Callback for updates on the current user's room connection status.
          zg.on("roomStateUpdate", (roomID, state, errorCode, extendedData) => {
            if (state === "DISCONNECTED") {
              // Disconnected from the room
              // * Can be used to show disconnected status for a user (especially useful in a group call)
            }

            if (state === "CONNECTING") {
              // Connecting to the room
              // * Can be used to show connecting status for a user (especially useful in a group call)
            }

            if (state === "CONNECTED") {
              // Connected to the room
              // * Can be used to show connected status for a user (especially useful in a group call)
            }
          });

          // Callback for updates on the status of ther users in the room.
          zg.on("roomUserUpdate", async (roomID, updateType, userList) => {
            // console.warn(`roomUserUpdate: room ${roomID}, user ${updateType === "ADD" ? "added" : "left"} `,
            //   JSON.stringify(userList)
            // );
            if (updateType !== "ADD") {
              handleDisconnect();
            } else {
              // const current_users = JSON.stringify(userList);
              // * We can use current_users_list to build dynamic UI in a group call
              const remoteStream = await zg.startPlayingStream(userID);

              // Get the audio tag.
              const remoteAudio = document.getElementById("remote-audio");
              // The local stream is a MediaStream object. You can render audio by assigning the local stream to the srcObject property of video or audio.

              if (remoteStream) {
                remoteAudio.srcObject = remoteStream;
              }
              remoteAudio.play();
            }
          });

          // Callback for updates on the status of the streams in the room.
          zg.on(
            "roomStreamUpdate",
            async (roomID, updateType, streamList, extendedData) => {
              if (updateType === "ADD") {
                // New stream added, start playing the stream.
                // console.log(
                //   "ADD",
                //   roomID,
                //   updateType,
                //   streamList,
                //   extendedData
                // );

                // * It would be quite useful to create and play multiple audio streams in a group call
              } else if (updateType === "DELETE") {
                // Stream deleted, stop playing the stream.
                // console.log(
                //   "DELETE",
                //   roomID,
                //   updateType,
                //   streamList,
                //   extendedData
                // );

                // * Can be used to drop audio streams (more useful in a group call)
              }
            }
          );

          zg.on("playerStateUpdate", (result) => {
            // Callback for updates on stream playing status.
            // ...
            // * Can be used to display realtime status of a remote audio stream (Connecting, connected & Disconnected)
          });

          zg.on("playQualityUpdate", (streamID, stats) => {
            // Callback for reporting stream playing quality.
            // * Can be used to display realtime quality of a remote audio stream
          });
        }
      }).catch((err) => {
        console.log(err);
      });

    return () => {
      subscriptions.current.forEach((sub) => {
        sub?.unsubscribe();
      });

      if (audioStreamRef.current) {
        audioStreamRef.current.getTracks().forEach((track) => {
          track.stop();
        });
      };

    };
  }, []);

  const [seconds, setSeconds] = useState(0);

  useEffect(() => {
    let timer;
    if (status === "ONGOING") {
      // Start the timer when the call is accepted
      timer = setInterval(() => {
        setSeconds(prevSeconds => prevSeconds + 1);
      }, 1000);
    } else {
      // Clear the timer when the dialog is closed
      setSeconds(0);
    }

    return () => {
      clearInterval(timer);
    };
  }, [status]);

  // Format the timer into MM:SS format
  const formatTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${minutes < 10 ? '0' : ''}${minutes}:${secs < 10 ? '0' : ''}${secs}`;
  };

  return (
    <>
      <Dialog
        open={open}
        TransitionComponent={Transition}
        keepMounted
        onClose={handleDisconnect}
        aria-describedby="alert-dialog-slide-description"
        PaperProps={{
          sx: {
            borderRadius: 3, // Rounder corners
            backgroundColor: '#f9fafb', // Light background
            boxShadow: 5, // Subtle shadow
          },
        }}
      >
        <DialogContent>
          <Stack
            direction="column"
            p={1.5}
            justifyContent="center"
            alignItems="center"
          >
            {/* Remote Audio Stack */}
            <Stack direction="column" justifyContent="center" p={2}>
              <Stack alignItems="center">
                <Avatar
                  sx={{ height: 300, width: 300, border: '4px solid #4caf50' }} // Add border for contrast
                  src={call_details?.from?.avatar}
                />
                <Typography variant="h4" mt={2}>
                  {call_details?.from.firstName}
                </Typography>
              </Stack>
              <audio id="remote-audio" controls={false} />
            </Stack>
            {/* Local Audio Stack */}
            <Stack>
              <audio id="local-audio" controls={false} />
            </Stack>
            <Stack mt={2}>
              <Typography variant="h5">{formatTime(seconds)}</Typography>
              {userBusy && <Typography variant="h6">{"User is on another call"}</Typography>}
            </Stack>
          </Stack>
        </DialogContent>
        <DialogActions sx={{ justifyContent: "center" }}>
          <IconButton
            onClick={handleDisconnect}
            sx={{
              backgroundColor: '#f44336',
              transition: '0.1s ease-in-out',
              color: '#fff',
              '&:hover': {
                backgroundColor: '#e53935',
                transform: 'scale3d(1.1, 1.1, 1.1)',
              },
            }}
          >
            <PhoneX size={40} />
          </IconButton>
        </DialogActions>
      </Dialog>
    </>
  );
};

export default CallDialog;